mod core;
#[allow(dead_code)]#[path="../affine-lp/dsu.rs"]mod dsu;
#[path="../setup/fast.rs"]mod fast;
use hec_native_ic::{counted,fp::Fp,jac::Curve,poly::Poly,rng::Rng,oracle::{split_reference,OracleStats}};
fn main(){counted::disable();println!("p\tsm\tcase\trep\tmodulus\tanchor\tt\tcounts");let mut calls=0;for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,_,_)=fast::prepare(&c);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026112600^p);for sm in [1,17]{let d=c.mul(&base,sm);for case in 0..2{let qualification=1+rng.below(ell-1);let target=c.mul(&d,qualification);let mut prior=None;for rep in 0..2{counted::reset();let r=core::solve(&c,&d,&target,ell,false);let counts=counted::snapshot();counted::disable();assert_eq!(r.relations,1);assert_eq!(r.k,None);let anchor=c.add(&target,&c.mul(&d,r.anchors));let v=anchor.v.add(&anchor.u.scale(r.parameter,&c.fp),&c.fp);let h=c.f.sub(&v.mul(&v,&c.fp),&c.fp).div_exact(&anchor.u,&c.fp);let roots=split_reference(&h,&c.fp,&mut OracleStats::default()).unwrap();let mut total=anchor;for &(x,m)in roots.as_slice(){for _ in 0..m{total=c.add_place(&total,x,v.eval(x,&c.fp));}}assert!(c.is_zero(&total));let signature=(r.anchors,r.parameter,counts.clone());if let Some(prior)=&prior{assert_eq!(prior,&signature)}else{prior=Some(signature)}for(modulus,v)in counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{modulus}\t{}\t{}\t{}",r.anchors,r.parameter,v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}calls+=1;}}}}assert_eq!(calls,24);eprintln!("prefix_calls=24 all_first_rows_original_group_verified=true no_target_solve_claim=true exact_repeats=true");}
